class Solution {
public:
    string sortVowels(string s) {
        int count[128] = {0};
        const string vowels = "AEIOUaeiou";
        for (char c : s) {
            if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u' ||
                c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U') {
                count[(int)c]++;
            }
        }
        int vi = 0;
        for (int i = 0; i < (int)s.size(); i++) {
            char c = s[i];
            if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u' ||
                c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U') {
                while (count[(int)vowels[vi]] == 0) vi++;
                s[i] = vowels[vi];
                count[(int)vowels[vi]]--;
            }
        }
        return s;
    }
};
